INSERT INTO tabs (id,title,play_json) VALUES
('work_ghost_261128','คืนที่สอง บ้านพักเลขที่ 13','{"entry":"arrival","variables":[],"advanced":{"people":{"may":{"name":"เมย์","role":"friend","age":25},"win":{"name":"วิน","role":"friend","age":27},"keeper":{"name":"ลุงชาญ","role":"keeper","age":63}},"relations":{"may":{"win":-20},"win":{"may":10}},"formulas":{"courage":{"name":"ความกล้า","expr":{"op":"-","args":[100,{"var":"ghost_fear"}]}},"escape":{"name":"โอกาสรอด","expr":{"op":"max","args":[5,{"op":"min","args":[95,{"op":"+","args":[{"formula":"courage"},{"op":"/","args":[{"var":"ghost_evidence"},2]},{"op":"/","args":[{"var":"ghost_trust"},4]}]}]}]}},"item_count":{"name":"จำนวนของ","expr":{"op":"count","args":[{"var":"ghost_items"}]}},"item_list":{"name":"รายชื่อของ","expr":{"op":"join","args":[{"var":"ghost_items"}," / "]}}}}}');
INSERT INTO variables (id,definition_json) VALUES
('ghost_fear','{"id":"ghost_fear","name":"ความกลัว","type":"number","initial":10,"min":0,"max":100,"owner":"work_ghost_261128"}'),
('ghost_trust','{"id":"ghost_trust","name":"ความไว้ใจ","type":"number","initial":45,"min":0,"max":100,"owner":"work_ghost_261128"}'),
('ghost_evidence','{"id":"ghost_evidence","name":"หลักฐาน","type":"number","initial":0,"min":0,"max":100,"owner":"work_ghost_261128"}'),
('ghost_money','{"id":"ghost_money","name":"เงินสด","type":"number","initial":2500,"min":0,"max":100000,"owner":"work_ghost_261128"}'),
('ghost_night','{"id":"ghost_night","name":"คืนที่","type":"number","initial":1,"min":1,"max":2,"owner":"work_ghost_261128"}'),
('ghost_age','{"id":"ghost_age","name":"อายุ","type":"number","initial":26,"min":0,"max":100,"owner":"work_ghost_261128"}'),
('ghost_cost','{"id":"ghost_cost","name":"ค่าเครื่องราง","type":"number","initial":900,"min":0,"max":10000,"owner":"work_ghost_261128"}'),
