INSERT INTO mechanisms (id,definition_json) VALUES
('ghost_ready','{"id":"ghost_ready","name":"พร้อมเผชิญหน้า","owner":"work_ghost_261128","mode":"all","conditions":[{"variable":"ghost_evidence","op":"gte","value":45},{"variable":"ghost_trust","op":"gte","value":40}]}'),
('ghost_canpay','{"id":"ghost_canpay","name":"มีเงินซื้อเครื่องราง","owner":"work_ghost_261128","mode":"all","conditions":[{"variable":"ghost_money","op":"gte","value":900}]}');
INSERT INTO nodes (tab_id,id,title,domain,type,ageMin,ageMax,x,y,play_json) VALUES
('work_ghost_261128','arrival','คืนที่ 1 — บ้านพักเลขที่ 13','life','decision',20,80,40,40,'{"kind":"question","text":"ฝนตกหนักจนถนนถูกตัดขาด คุณ @[var:ghost_name] กับเมย์และวินต้องค้างในบ้านพักเก่าริมป่า ลุงชาญยื่นกุญแจหมายเลข 13 ให้ พร้อมกำชับว่า หลังตีสองห้ามตอบเสียงเรียกชื่อ แม้จะเป็นเสียงคนที่คุณรัก","end":false,"choices":[{"id":"c1","label":"ถามว่าทำไมถึงห้ามตอบ","result":"ลุงชาญมองคุณอยู่นาน ก่อนเล่าว่าเคยมีคนหายไป","effects":[{"variable":"ghost_evidence","op":"add","value":10},{"variable":"ghost_trust","op":"add","value":5}],"worldEffects":[{"kind":"memory","person":"keeper","text":"ลุงชาญเคยเตือนเรื่องเสียงเรียกชื่อ","id":"warning"}]},{"id":"c2","label":"หัวเราะแล้วรับกุญแจ","result":"เมย์ไม่หัวเราะด้วย เธอมองประตูเหมือนเห็นบางอย่าง","effects":[{"variable":"ghost_fear","op":"add","value":5},{"variable":"ghost_trust","op":"add","value":-5}]}]}'),
('work_ghost_261128','warning','สิ่งที่ลุงไม่ยอมพูด','life','decision',20,80,350,40,'{"kind":"question","text":"ลุงชาญเอารูปถ่ายเก่าออกมา เด็กผู้หญิงยืนอยู่หน้าห้อง 13 แต่เงาบนพื้นกลับเป็นผู้ใหญ่ เขาเสนอเครื่องรางราคา @[var:ghost_cost] บาท คุณมีเงิน @[var:ghost_money] บาท","end":false,"choices":[{"id":"c1","label":"ซื้อเครื่องราง","result":"เครื่องรางเย็นจัดราวกับเพิ่งขึ้นมาจากน้ำ","effects":[{"variable":"ghost_money","op":"add","expr":{"op":"-","args":[0,{"var":"ghost_cost"}]}},{"variable":"ghost_items","op":"append","value":"เครื่องราง"},{"variable":"ghost_fear","op":"add","value":-5}],"when":{"mechanism":"ghost_canpay"}},{"id":"c2","label":"ขอรูปถ่ายแทน","result":"ลุงยอมให้รูป แต่ขอให้คุณอย่าเปิดด้านหลังในห้องพัก","effects":[{"variable":"ghost_items","op":"append","value":"รูปถ่าย"},{"variable":"ghost_evidence","op":"add","value":15}]},{"id":"c3","label":"ไม่เอาอะไร","result":"ลุงชาญพึมพำว่าคุณจะต้องกลับมาอีกครั้ง","effects":[]}]}'),
('work_ghost_261128','room','เสียงจากห้องน้ำ','life','decision',20,80,660,40,'{"kind":"question","text":"เวลา 01:47 น. กระจกมีไอน้ำเกาะ ทั้งที่ไม่ได้เปิดน้ำอุ่น เมย์เห็นข้อความเขียนจากด้านในกระจกว่า “วินรู้” วินยืนยันว่าไม่รู้เรื่อง","end":false,"choices":[{"id":"c1","label":"เชื่อเมย์และถ่ายรูป","result":"วินโกรธที่คุณเชื่อเมย์","effects":[{"variable":"ghost_trust","op":"add","value":10},{"variable":"ghost_evidence","op":"add","value":15}],"worldEffects":[{"kind":"relation","from":"may","to":"win","value":-65},{"kind":"knowledge","person":"may","key":"suspect","value":"รู้"},{"kind":"memory","person":"may","text":"เห็นข้อความว่าวินรู้","id":"mirror"}]},{"id":"c2","label":"ถามวินตรง ๆ","result":"วินเงียบแล้วปิดประตูห้องน้ำ","effects":[{"variable":"ghost_evidence","op":"add","value":5}],"worldEffects":[{"kind":"knowledge","person":"win","key":"questioned","value":true}]},{"id":"c3","label":"ลบข้อความออก","result":"ตัวอักษรกลับขึ้นใหม่เป็นชื่อของคุณ","effects":[{"variable":"ghost_fear","op":"add","value":20}],"worldEffects":[{"kind":"memory","person":"may","text":"ข้อความบนกระจกถูกลบแล้วกลับมา","id":"erased"}]}]}'),
('work_ghost_261128','mirror','รูปที่ไม่ควรมี','life','decision',20,80,970,40,'{"kind":"question","text":"ภาพในมือถือมีผู้หญิงผมยาวอยู่ระหว่างเมย์กับวิน ทั้งที่ตรงนั้นว่างเปล่า เมื่อซูมเข้าไป ใบหน้าของเธอเหมือนเมย์ แต่มีรอยช้ำรอบคอ","end":false,"choices":[{"id":"c1","label":"เก็บหลักฐานและให้เมย์ดู","result":"เมย์ร้องไห้ เธอบอกว่าเคยฝันเห็นผู้หญิงคนนี้","effects":[{"variable":"ghost_evidence","op":"add","value":20},{"variable":"ghost_trust","op":"add","value":10},{"variable":"ghost_fear","op":"add","value":10}],"worldEffects":[{"kind":"memory","person":"may","text":"ภาพผีหน้าคล้ายเมย์","id":"photo"},{"kind":"knowledge","person":"may","key":"photo","value":true}]},{"id":"c2","label":"ลบภาพไม่ให้ใครรู้","result":"หน้าจอดับเอง และมีเสียงหัวเราะดังจากมือถือ","effects":[{"variable":"ghost_fear","op":"add","value":20},{"variable":"ghost_trust","op":"add","value":-10}],"worldEffects":[{"kind":"knowledge","person":"win","key":"photo","value":"ไม่รู้"}]}]}'),
('work_ghost_261128','win','คำสารภาพครึ่งเดียว','life','decision',20,80,40,275,'{"kind":"question","text":"วินเล่าว่าเมื่อสิบปีก่อนพี่สาวของเขาเคยมาพักที่นี่แล้วหายตัวไป แต่เขาไม่เคยบอกเมย์ เพราะกลัวเธอจะไม่ยอมมา","end":false,"choices":[{"id":"c1","label":"สัญญาว่าจะช่วยค้นหา","result":"วินยื่นกุญแจเก่าให้คุณ","effects":[{"variable":"ghost_items","op":"append","value":"กุญแจเก่า"},{"variable":"ghost_evidence","op":"add","value":20},{"variable":"ghost_trust","op":"add","value":5}],"worldEffects":[{"kind":"knowledge","person":"win","key":"sister","value":true},{"kind":"memory","person":"win","text":"วินสารภาพว่าพี่สาวหายตัว","id":"sister"}]},{"id":"c2","label":"บอกเมย์ทันที","result":"เมย์ตบโต๊ะและถามว่าวินพาเธอมาทำไม","effects":[{"variable":"ghost_evidence","op":"add","value":15},{"variable":"ghost_trust","op":"add","value":10}],"worldEffects":[{"kind":"knowledge","person":"may","key":"sister","value":true},{"kind":"relation","from":"may","to":"win","value":-80}]}]}'),
('work_ghost_261128','knock','02:13 — เคาะสามครั้ง','life','decision',20,80,350,275,'{"kind":"question","text":"เสียงเคาะประตูดังสามครั้ง ตามด้วยเสียงของเมย์เรียกชื่อคุณ แต่เมย์ตัวจริงนั่งตัวสั่นอยู่ข้างเตียง ลูกบิดหมุนช้า ๆ จากด้านนอก","end":false,"choices":[{"id":"c1","label":"ไม่ตอบและขวางประตู","result":"เสียงเรียกหยุดไป แต่มีรอยนิ้วมือเปียกบนผนัง","effects":[{"variable":"ghost_fear","op":"add","value":5},{"variable":"ghost_trust","op":"add","value":10}],"worldEffects":[{"kind":"memory","person":"may","text":"คุณไม่ตอบเสียงเรียก","id":"silent"}]},{"id":"c2","label":"ถามว่าใครอยู่ข้างนอก","result":"เสียงตอบกลับด้วยน้ำเสียงของคุณเอง","effects":[{"variable":"ghost_fear","op":"add","value":25}],"worldEffects":[{"kind":"memory","person":"may","text":"คุณตอบเสียงเรียกหลังตีสอง","id":"answered"},{"kind":"knowledge","person":"may","key":"answered","value":true}]},{"id":"c3","label":"ชูเครื่องรางแล้วถอย","result":"เสียงกรีดร้องลอยมาจากท่อระบายน้ำ","effects":[{"variable":"ghost_fear","op":"add","value":-10},{"variable":"ghost_evidence","op":"add","value":10}],"when":{"op":"contains","args":[{"var":"ghost_items"},"เครื่องราง"]}}]}'),
('work_ghost_261128','hall','ทางเดินที่ยาวขึ้น','life','decision',20,80,660,275,'{"kind":"question","text":"ประตูห้องเปิดเอง ทางเดินที่เคยยาวห้าเมตรทอดไปจนมองไม่เห็นปลาย ที่พื้นมีรอยเท้าเปียกเดินย้อนเข้ามาจากห้อง 13","end":false,"choices":[{"id":"c1","label":"วิ่งตามรอยเท้า","result":"คุณพบประตูห้องเก็บเอกสารที่ไม่เคยอยู่ตรงนี้","effects":[{"variable":"ghost_fear","op":"add","value":10},{"variable":"ghost_evidence","op":"add","value":10}]},{"id":"c2","label":"พาทุกคนกลับห้อง","result":"คุณได้ยินเสียงเด็กนับถอยหลังหลังประตู","effects":[{"variable":"ghost_trust","op":"add","value":5}]},{"id":"c3","label":"ใช้กุญแจเก่าเปิดห้องซ่อน","result":"กุญแจหมุนเองก่อนที่คุณจะจับมัน","effects":[{"variable":"ghost_evidence","op":"add","value":15}],"when":{"op":"contains","args":[{"var":"ghost_items"},"กุญแจเก่า"]}}]}'),
('work_ghost_261128','archive','สมุดทะเบียนคนตาย','life','decision',20,80,970,275,'{"kind":"question","text":"สมุดทะเบียนระบุชื่อพี่สาววินว่าเข้าพักวันที่ 13 พฤศจิกายน สิบปีก่อน บรรทัดถัดไปเป็นชื่อ @[var:ghost_name] พร้อมวันที่พรุ่งนี้ ช่องเวลาออกยังว่างอยู่","end":false,"choices":[{"id":"c1","label":"ถ่ายหน้าทะเบียนไว้","result":"หมึกชื่อของคุณค่อย ๆ ซึมออกมาจากกระดาษ","effects":[{"variable":"ghost_evidence","op":"add","value":20},{"variable":"ghost_items","op":"append","value":"หน้าทะเบียน"}],"worldEffects":[{"kind":"memory","person":"win","text":"พบชื่อผู้เล่นในทะเบียนคนตาย","id":"register"}]},{"id":"c2","label":"ฉีกหน้าชื่อของคุณ","result":"กระดาษร้องเสียงเหมือนคนถูกปลุก","effects":[{"variable":"ghost_fear","op":"add","value":15},{"variable":"ghost_evidence","op":"add","value":5}],"worldEffects":[{"kind":"knowledge","person":"win","key":"torn","value":true}]},{"id":"c3","label":"อ่านด้านหลังรูปถ่าย","result":"ข้อความบอกว่าคนตายต้องการให้มีคนจำชื่อเธอ","effects":[{"variable":"ghost_evidence","op":"add","value":25},{"variable":"ghost_truth","op":"set","value":true}],"when":{"op":"contains","args":[{"var":"ghost_items"},"รูปถ่าย"]}}]}'),
('work_ghost_261128','morning','06:00 — คืนแรกจบแล้ว','life','decision',20,80,40,510,'{"kind":"question","text":"แดดเช้าส่องเข้ามา แต่โทรศัพท์ทั้งสามเครื่องขึ้นวันที่เดิม ถนนยังถูกน้ำปิด ลุงชาญบอกว่าคืนที่สองคือคืนที่บ้านจะเรียกเก็บสิ่งที่มันจดจำ","end":false,"choices":[{"id":"c1","label":"พักแล้วกลับไปห้อง 13","result":"คุณตั้งปลุกไว้ก่อนตีสอง","effects":[{"variable":"ghost_night","op":"set","value":2},{"variable":"ghost_fear","op":"add","value":-10}],"worldEffects":[{"kind":"advance","value":1},{"kind":"schedule","to":"return","delay":0}],"nextPool":"return"},{"id":"c2","label":"ไปถามลุงชาญก่อนค่ำ","result":"ลุงชาญรออยู่หน้าประตูเหมือนรู้อยู่แล้ว","effects":[{"variable":"ghost_night","op":"set","value":2}],"worldEffects":[{"kind":"advance","value":1}]}]}'),
('work_ghost_261128','keeper','ความลับของเจ้าของบ้าน','life','decision',20,80,350,510,'{"kind":"question","text":"ลุงชาญสารภาพว่าเคยปิดห้อง 13 เพื่อซ่อนหลักฐานการหายตัว เขาไม่รู้ว่าสิ่งที่อยู่ข้างในยังเป็นมนุษย์หรือไม่","end":false,"choices":[{"id":"c1","label":"ขอชื่อจริงของผู้หญิง","result":"ชื่อบนกระดาษคือ ‘ดาว’","effects":[{"variable":"ghost_truth","op":"set","value":true},{"variable":"ghost_evidence","op":"add","value":15}],"worldEffects":[{"kind":"person","id":"dao","value":{"literal":{"name":"ดาว","role":"ghost"}}},{"kind":"memory","person":"keeper","text":"ลุงบอกชื่อผู้หญิงคือดาว","id":"name"}]},{"id":"c2","label":"ขู่จะเปิดโปงเรื่องทั้งหมด","result":"ลุงยอมให้กุญแจ แต่ไม่กล้าสบตาคุณ","effects":[{"variable":"ghost_evidence","op":"add","value":10},{"variable":"ghost_items","op":"append","value":"กุญแจห้องใต้ดิน"}],"worldEffects":[{"kind":"knowledge","person":"keeper","key":"threatened","value":true}]}]}'),
('work_ghost_261128','return','คืนที่ 2 — กลับมาที่ห้องเดิม','life','decision',20,80,660,510,'{"kind":"question","text":"คุณกลับมาที่ประตูเดิมอีกครั้ง คืนนี้ตัวเลขบนกุญแจเปลี่ยนเป็น 14 ทั้งที่มีเพียง 13 ห้อง ของที่มี @[formula:item_count] ชิ้น: @[formula:item_list|ไม่มีของ] ความกล้าเหลือ @[formula:courage] แต้ม","end":false,"choices":[{"id":"c1","label":"เรียกเพื่อนมาคุยเรื่องเมื่อคืน","result":"ทั้งสามนั่งล้อมโต๊ะใต้หลอดไฟที่กะพริบ","effects":[]},{"id":"c2","label":"อยู่เฝ้าประตูคนเดียว","result":"เงาของคุณขยับก่อนตัวคุณ","effects":[{"variable":"ghost_fear","op":"add","value":10}]}],"event":{"once":true,"cooldown":1,"fromDay":1,"minAge":20,"ageVar":"ghost_age"}}'),
('work_ghost_261128','conflict','คนที่ไม่ไว้ใจกัน','life','decision',20,80,970,510,'{"kind":"question","text":"เมย์กับวินมองหน้ากัน ไม่มีใครกล้าพูดถึงเมื่อคืน","end":false,"choices":[{"id":"c1","label":"ขอให้ทั้งคู่หยุดทะเลาะ","result":"เมย์ยอมช่วย แต่ขอให้วินเดินนำ","effects":[{"variable":"ghost_trust","op":"add","value":10}],"worldEffects":[{"kind":"relation","from":"may","to":"win","value":-10}]},{"id":"c2","label":"ถามว่าใครกำลังโกหก","result":"วินชี้ไปที่กระจกซึ่งไม่มีเงาของเมย์","effects":[{"variable":"ghost_fear","op":"add","value":15},{"variable":"ghost_evidence","op":"add","value":10}]}],"variants":[{"when":{"op":"lt","args":[{"world":"relations.may.win"},-40]},"text":"เมย์ผลักเก้าอี้หนีวิน “นายปิดบังอะไรอีก? เมื่อคืนฉันเห็นข้อความกับตา” วินไม่ยอมมองหน้าเธอ"},{"when":{"op":"eq","args":[{"world":"knowledge.may.sister"},true]},"text":"เมย์ถามวินถึงพี่สาวอีกครั้ง คราวนี้วินยอมเล่าต่อหน้าเธอ"}]}'),
('work_ghost_261128','repeat','02:13 — เสียงเดิมกลับมา','life','decision',20,80,40,745,'{"kind":"question","text":"เสียงเคาะสามครั้งดังขึ้นอีกครั้ง คราวนี้เสียงเรียกชื่อคุณมาจากใต้เตียง ไม่ใช่ประตู","end":false,"choices":[{"id":"c1","label":"ปลุกเพื่อนที่ไว้ใจได้","result":"คุณได้ยินเสียงฝีเท้าของเพื่อนที่เดินมาช่วย","effects":[{"variable":"ghost_trust","op":"add","value":5}]},{"id":"c2","label":"ตรวจใต้เตียงด้วยตัวเอง","result":"ใต้เตียงมีบันไดลงไปชั้นใต้ดิน","effects":[{"variable":"ghost_fear","op":"add","value":10},{"variable":"ghost_evidence","op":"add","value":10}]},{"id":"c3","label":"ใช้เครื่องราง","result":"เครื่องรางแตก เศษกระดาษข้างในมีชื่อดาว","effects":[{"variable":"ghost_truth","op":"set","value":true},{"variable":"ghost_items","op":"remove","value":"เครื่องราง"}],"when":{"op":"contains","args":[{"var":"ghost_items"},"เครื่องราง"]}}],"variants":[{"when":{"op":"eq","args":[{"world":"knowledge.may.answered"},true]},"text":"เสียงจากใต้เตียงพูดประโยคเดียวกับที่คุณตอบไปเมื่อคืน แล้วหัวเราะ “คราวนี้ถึงตาแกตอบอีกแล้ว”"},{"when":{"op":"eq","args":[{"world":"knowledge.may.photo"},true]},"text":"มือถือเปิดภาพที่ถ่ายเมื่อคืนเอง ผู้หญิงในภาพหันหน้าเข้าหากล้อง แล้วชี้ลงใต้เตียง"}]}'),
('work_ghost_261128','companion','คนที่เดินตามคุณ','life','decision',20,80,350,745,'{"kind":"question","text":"@[world:people.A.name] บอกว่าจะไม่ทิ้งคุณไว้คนเดียว แต่ตอนเดินลงบันได คุณได้ยินเสียงของเขาเรียกจากห้องข้างบนอีกครั้ง","end":false,"choices":[{"id":"c1","label":"จับมือและเดินต่อ","result":"มือของเพื่อนอุ่น แต่อีกเสียงยังร้องเรียกอยู่","effects":[{"variable":"ghost_trust","op":"add","value":10}],"worldEffects":[{"kind":"memory","person":"A","text":"ร่วมลงชั้นใต้ดินกับผู้เล่น","id":"together"}]},{"id":"c2","label":"ขอให้บอกความทรงจำเมื่อคืน","result":"เพื่อนเล่ารายละเอียดที่มีเพียงคุณกับเขารู้","effects":[{"variable":"ghost_evidence","op":"add","value":10},{"variable":"ghost_fear","op":"add","value":-5}]}],"roles":{"A":{"op":"eq","args":[{"world":"people.A.role"},"friend"]}}}'),
('work_ghost_261128','basement','ห้องใต้ดิน','life','decision',20,80,660,745,'{"kind":"question","text":"กลางห้องมีเก้าอี้ไม้หันเข้าผนังและสมุดทะเบียนเล่มเดิม ผู้หญิงที่ไม่มีเงานั่งอยู่บนเก้าอี้ เธอถามว่า “ยังจำชื่อฉันได้ไหม”","end":false,"choices":[{"id":"c1","label":"เรียกชื่อดาว","result":"ผู้หญิงค่อย ๆ หันมามองคุณ","effects":[{"variable":"ghost_fear","op":"add","value":-10},{"variable":"ghost_trust","op":"add","value":5}],"when":{"op":"eq","args":[{"var":"ghost_truth"},true]}},{"id":"c2","label":"ยื่นหลักฐานทั้งหมดให้ดู","result":"เธอมองหลักฐานทีละชิ้นแล้วร้องไห้","effects":[{"variable":"ghost_evidence","op":"add","value":10}],"worldEffects":[{"kind":"memory","person":"win","text":"ยื่นหลักฐานให้ผู้หญิงในห้องใต้ดิน","id":"proof"}]},{"id":"c3","label":"หนีขึ้นบันได","result":"บันไดด้านบนปิดลงเอง","effects":[{"variable":"ghost_fear","op":"add","value":20}]}]}'),
('work_ghost_261128','reveal','สิ่งที่บ้านต้องการ','life','decision',20,80,970,745,'{"kind":"question","text":"หญิงสาวบอกว่าบ้านไม่ได้อยากได้ชีวิตใหม่ แต่มันอยากให้ทุกคนลืมชื่อคนที่หายไป ทุกครั้งที่ใครปิดบังความจริง มันจะสร้างคืนเดิมขึ้นมาอีก","end":false,"choices":[{"id":"c1","label":"สัญญาว่าจะเปิดเผยความจริง","result":"เธอยื่นสมุดทะเบียนให้คุณ","effects":[{"variable":"ghost_truth","op":"set","value":true},{"variable":"ghost_evidence","op":"add","value":10}],"worldEffects":[{"kind":"knowledge","person":"may","key":"truth","value":true},{"kind":"memory","person":"may","text":"สัญญาจะเปิดเผยความจริง","id":"promise"}]},{"id":"c2","label":"ขอให้ทุกคนกลับออกไปก่อน","result":"ประตูเปิดออก แต่เสียงร้องตามหลังมา","effects":[{"variable":"ghost_fear","op":"add","value":5}]}]}'),
('work_ghost_261128','chase','ทางเดินไม่มีทางออก','life','decision',20,80,40,980,'{"kind":"question","text":"ไฟดับทีละดวง เสียงเท้าเดินตามหลังคุณ ยิ่งวิ่งก็ยิ่งกลับมาที่ประตู 13 โอกาสหนีตามสภาพของคุณตอนนี้คือ @[formula:escape]% ","end":false,"choices":[{"id":"c1","label":"หยุดฟังเสียงแล้วหาทางออก","result":"คุณพบแสงลอดจากใต้ประตู","effects":[{"variable":"ghost_fear","op":"add","value":-5}]},{"id":"c2","label":"วิ่งสุดแรง","result":"คุณวิ่งฝ่าความมืดโดยไม่หันกลับ","effects":[{"variable":"ghost_fear","op":"add","value":10}]}]}'),
('work_ghost_261128','judgment','ตรวจชะตากรรม','life','decision',20,80,350,980,'{"kind":"question","text":"","end":false,"choices":[],"auto":{"branches":[{"when":{"op":"and","args":[{"var":"ghost_truth"},{"mechanism":"ghost_ready"}]},"to":"free"},{"when":{"op":"gte","args":[{"var":"ghost_trust"},50]},"chance":{"formula":"escape"},"to":"escape"},{"when":{"op":"lt","args":[{"var":"ghost_fear"},70]},"chance":45,"to":"alone"}],"fallback":"trapped"}}'),
('work_ghost_261128','free','ตอนจบ — ชื่อที่ถูกจดจำ','life','end',20,80,660,980,'{"kind":"question","text":"รุ่งเช้าเป็นวันใหม่จริง ๆ เมย์กับวินยืนข้างคุณเมื่อเจ้าหน้าที่มารับสมุดทะเบียน บ้านเลขที่ 13 เงียบลงเป็นครั้งแรก ชื่อดาวไม่ถูกลบอีกแล้ว","end":true,"choices":[]}'),
('work_ghost_261128','escape','ตอนจบ — รอดแต่ไม่จบ','life','end',20,80,970,980,'{"kind":"question","text":"คุณกับเพื่อนออกมาถึงถนนได้ แต่เมื่อเปิดโทรศัพท์ มีข้อความใหม่จากเบอร์ของคุณเอง: “คืนที่สามเมื่อไหร่ดี?”","end":true,"choices":[]}'),
('work_ghost_261128','alone','ตอนจบ — คนเดียวที่กลับมา','life','end',20,80,40,1215,'{"kind":"question","text":"คุณตื่นอยู่ริมถนน คนขับรถบอกว่าไม่เคยมีใครเดินทางมากับคุณ แต่ในกระเป๋ามีรูปถ่ายเพื่อนทั้งสองยืนอยู่หลังประตู 13","end":true,"choices":[]}'),
('work_ghost_261128','trapped','ตอนจบ — แขกคนใหม่','life','end',20,80,350,1215,'{"kind":"question","text":"เวลา 06:00 น. คุณลืมตาในห้องรับรอง ลุงชาญไม่อยู่แล้ว คุณกำลังถือกุญแจหมายเลข 13 และได้ยินเสียงรถของแขกชุดใหม่จอดหน้าบ้าน","end":true,"choices":[]}');
